# Wire the SCIF sources into the generated Xcode project.
#
#   gem install xcodeproj
#   TEAM_ID=ABCDE12345 APP_BUNDLE_ID=us.innotel.scif APP_BUILD=42 ruby scripts/ios-project.rb
#
# A .xcodeproj is a directory of plists and a very long pbxproj file. Committing
# one means every build-number bump and every new source file is a merge
# conflict, so the project is generated by `npx cap add ios` and shaped here.
# Everything this script sets is also what you would click in Xcode:
#
#   * the four Swift files, added to the App target's sources
#   * CODE_SIGN_ENTITLEMENTS (the push entitlement)
#   * DEVELOPMENT_TEAM, PRODUCT_BUNDLE_IDENTIFIER, versions
#
# Idempotent: running it twice changes nothing the second time.

require 'xcodeproj'

project_path = File.expand_path('../ios/App/App.xcodeproj', __dir__)
abort "ios-project: no project at #{project_path} — run \"npx cap add ios\" first" unless Dir.exist?(project_path)

project = Xcodeproj::Project.open(project_path)
target = project.targets.find { |candidate| candidate.name == 'App' }
abort 'ios-project: the template has no App target' if target.nil?

app_dir = File.expand_path('../ios/App/App', __dir__)
group = project.main_group['App'] || project.main_group.new_group('App', 'App')

added = []
Dir.glob(File.join(app_dir, '*.swift')).sort.each do |path|
  name = File.basename(path)
  reference = group.files.find { |file| file.path == name } || group.new_reference(name)
  next if target.source_build_phase.files_references.include?(reference)

  target.add_file_references([reference])
  added << name
end

team = ENV['TEAM_ID'].to_s
bundle_id = ENV['APP_BUNDLE_ID'].to_s
version = ENV['APP_VERSION'].to_s
build = ENV['APP_BUILD'].to_s

target.build_configurations.each do |config|
  settings = config.build_settings
  settings['CODE_SIGN_ENTITLEMENTS'] = 'App/App.entitlements'
  settings['DEVELOPMENT_TEAM'] = team unless team.empty?
  settings['PRODUCT_BUNDLE_IDENTIFIER'] = bundle_id unless bundle_id.empty?
  settings['MARKETING_VERSION'] = version unless version.empty?
  # TestFlight rejects a build number it has already seen, so CI passes the run
  # number here rather than a value somebody has to remember to bump.
  settings['CURRENT_PROJECT_VERSION'] = build unless build.empty?
  # The template ships 14.0, and `||=` will never raise that — which is how the
  # first TestFlight upload came back with warning 90068: "Deployment target too
  # low... Starting in April 2027, iOS apps must target 15.0 or later". So raise
  # the floor on every deployment-target key the template set, including the
  # conditional [sdk=iphoneos*] variants.
  floor = ENV['APP_MIN_IOS'].to_s
  floor = '15.0' if floor.empty?
  floor_parts = floor.split('.').map(&:to_i)
  settings.keys.each do |key|
    next unless key =~ /\AIPHONEOS_DEPLOYMENT_TARGET(\[.*\])?\z/

    current = settings[key].to_s
    next unless current.empty? || (current.split('.').map(&:to_i) <=> floor_parts) == -1

    settings[key] = floor
  end
  # Automatic signing with -allowProvisioningUpdates: the App Store Connect key
  # in CI has the rights to create the certificate and profile it needs, so no
  # .p12 has to live in the repository.
  settings['CODE_SIGN_STYLE'] = 'Automatic'
  # No identity is forced here on purpose. Automatic signing fixes the signing
  # type at archive time (development, which needs a registered device), and it
  # treats a hand-set distribution identity as a conflict. CI archives without a
  # signature and lets "xcodebuild -exportArchive" sign for App Store with the
  # App Store Connect key, which needs no devices.
end

project.save

puts "ios-project: target App · bundle #{bundle_id.empty? ? '(template)' : bundle_id} · " \
     "team #{team.empty? ? '(template)' : team} · build #{build.empty? ? '(template)' : build}"
puts "ios-project: sources added this run: #{added.empty? ? 'none (already there)' : added.join(', ')}"
